import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from gradientEncoding ----
type Reading = { date: Date; temperature: number };

const DAYS = 366; // 2011-10-01 through 2012-09-30

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);

/** Synthetic daily temperature, shaped after a mild coastal year peaking in early September. */
const dailyTemperature: Reading[] = (() => {
  let weather = 0;
  return Array.from({ length: DAYS }, (_, day) => {
    // AR(1) weather term: fronts persist for days instead of flickering day to day.
    weather = weather * 0.86 + (random() - 0.5) * 6;
    const seasonal = 57 + 9 * Math.sin((2 * Math.PI * (day - 244)) / 365);
    return {
      date: new Date(Date.UTC(2011, 9, 1 + day)),
      temperature: Math.round((seasonal + weather) * 10) / 10
    };
  });
})();

const MARGIN = { top: 16, right: 20, bottom: 36, left: 52 };

// Namespaced so it cannot collide with another chart's gradient in the same document.
const GRADIENT_ID = 'gradient-encoding-turbo';

/** A dated value series; the stroke gradient colours each point by its own value. */
export type Data = { date: Date; temperature: number }[];

export default function GradientEncoding({ data = dailyTemperature, width }:
  { data?: Data; width: number }) {
  const height = Math.round(width * 0.54);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain(d3.extent(data, (d) => d.temperature) as [number, number])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const color = useMemo(
    () => d3.scaleSequential(y.domain(), d3.interpolateTurbo),
    [y]
  );

  const path = useMemo(
    () =>
      d3
        .line<Reading>()
        .curve(d3.curveStep)
        .x((d) => x(d.date))
        .y((d) => y(d.temperature))(data) ?? '',
    [data, x, y]
  );

  // Offset 0 sits at the bottom of the y range, so each stop's color is the color of that y value.
  const stops = useMemo(
    () => d3.ticks(0, 1, 10).map((t) => ({ offset: t, color: color.interpolator()(t) })),
    [color]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x
        // Capped at 12 so the ticks stay monthly and the %b labels stay unique.
        .ticks(Math.min(12, Math.max(2, Math.round(innerWidth / 80))))
        .map((v) => ({ value: d3.timeFormat('%b')(v), offset: x(v) })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(() => {
    const values = y.ticks(5);
    return values.map((v, i) => ({
      value: i === values.length - 1 ? `${v}°F` : String(v),
      offset: y(v)
    }));
  }, [y]);

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Daily temperature line colored by a vertical gradient encoding its own value">
      <defs>
        <linearGradient
          id={GRADIENT_ID}
          gradientUnits="userSpaceOnUse"
          x1={0}
          y1={innerHeight}
          x2={0}
          y2={0}
        >
          {stops.map((s) => (
            <stop key={s.offset} offset={s.offset} stopColor={s.color} />
          ))}
        </linearGradient>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <path
          d={path}
          fill="none"
          stroke={`url(#${GRADIENT_ID})`}
          strokeWidth={1.75}
          strokeLinejoin="round"
          strokeLinecap="round"
        />
      </g>
    </svg>
  );
}
